  "Bạn có chắc chắn muốn phê duyệt hủy sự kiện này? Hành động này sẽ đóng toàn bộ bán vé, hủy các vé đã phát hành và bắt đầu tạo phiếu hoàn tiền cho mọi đơn hàng đã thanh toán.": "Are you sure you want to approve the cancellation of this event? This action will close all ticket sales, cancel issued tickets, and initiate the generation of refunds for all paid orders.",
  "Bạn có chắc chắn muốn phê duyệt sự kiện này?": "Are you sure you want to approve this event?",
  "Bạn có chắc chắn muốn tiếp tục?": "Are you sure you want to continue?",
  "Bạn có chắc chắn muốn từ chối sự kiện này? Vui lòng đảm bảo đã nhập lý do.": "Are you sure you want to decline this event? Please make sure to enter a reason.",
  "Bạn có chắc chắn muốn từ chối yêu cầu hủy? Sự kiện sẽ được mở bán lại và lý do từ chối sẽ được gửi ngay đến Ban tổ chức.": "Are you sure you want to decline the cancellation request? The event will be reopened and the reason for refusal will be immediately sent to the Organizing Committee.",
  "Bạn có chắc chắn muốn xóa sơ đồ ghế này không? Hành động này không thể hoàn tác.": "Are you sure you want to delete this seat plan? This action cannot be undone.",
  "Bạn có chắc chắn muốn áp dụng cấu hình sơ đồ ghế và vé của phiên này cho các phiên khác CÙNG ĐỊA ĐIỂM? Đối với các phiên khác địa điểm, cấu hình sẽ không được áp dụng.": "Are you sure you want to apply this session's seating and ticket configuration to other sessions at the SAME LOCATION? For sessions other than the location, the configuration will not be applied.",
  "Bạn có chắc chắn muốn ẩn sự kiện này khỏi hệ thống? Sự kiện sẽ không còn hiển thị với người dùng.": "Are you sure you want to hide this event from the system? The event will no longer be visible to users.",
  "Bạn có chắc chắn?": "Are you sure?",
  "Bạn có thể gửi lại yêu cầu với thông tin cập nhật.": "You can resubmit the request with updated information.",
  "Bạn có thể gửi phản hồi ngay khi sự kiện bắt đầu diễn ra hoặc sau khi kết thúc.": "You can send feedback as soon as the event starts or after it ends.",
  "Bạn có thể gửi yêu cầu cập nhật hồ sơ pháp lý và hồ sơ xác minh tại đây.": "You can submit a request to update legal documents and verification documents here.",
  "Bạn có thể kích hoạt lại tài khoản bất kỳ lúc nào khi cần.": "You can reactivate your account at any time if needed.",
