  ": Cứ sau 15p AI chỉ quét review trước cho Admin và đưa ra kết quả, giữ nguyên sự kiện ở trạng thái Chờ duyệt để Admin kiểm tra và quyết định.": ": Every 15 minutes, AI only scans the review first for Admin and gives the results, keeping the event in the Waiting for Approval state for Admin to check and decide.",
