  "Bạn chưa gửi yêu cầu nào. Điền form bên trái để đăng ký trở thành ban tổ chức.": "You haven't sent any requests yet. Fill out the form on the left to register to become an organizer.",
  "Bạn chưa đăng ký gói dịch vụ nào. Hãy chọn một gói phù hợp bên trên.": "You have not subscribed to any service package. Please select a suitable package above.",
  "Bạn có chắc chắn muốn hủy yêu cầu này? Yêu cầu gửi Admin sẽ bị hủy bỏ và trạng thái bán vé của sự kiện sẽ được khôi phục.": "Are you sure you want to cancel this request? The request to Admin will be canceled and the event's ticketing status will be restored.",
