  "Bạn có thể tải lên file chính sách chi tiết của sự kiện (định dạng PDF, không bắt buộc).": "You can upload a detailed event policy file (PDF format, optional).",
  "Bạn có thể tải sẵn 2 tài liệu này tại đây, khi bấm &quot;Áp dụng&quot; hệ thống sẽ tự động chuyển vào Bước 4 mà không cần tải lại.": "You can pre-download these two documents here. When you click \"Apply\", the system will automatically move to Step 4 without reloading.",
