  "Hạ cấp cần kiểm tra quota và áp dụng ở chu kỳ tiếp theo. Nếu chưa được mở tự động, vui lòng liên hệ quản trị viên để lên lịch chuyển gói.": "Downgrading requires checking quota and applying in the next cycle. If it has not been opened automatically, please contact your administrator to schedule package transfer.",
