  "Để sự kiện được kiểm duyệt và công khai bán vé, bạn cần cung cấp giấy phép tổ chức sự kiện hoặc hợp đồng địa điểm liên quan.": "In order for your event to be moderated and ticketed publicly, you will need to provide an event license or relevant venue contract.",
  "Định dạng": "Format",
  "Định dạng tài liệu này được hỗ trợ xem trực tiếp qua trình xem trực tuyến hoặc tải về.": "This document format is supported for direct viewing via online viewer or download.",
  "Định dạng: JPG, PNG, WEBP (Tối đa 10MB). Khuyến khích chụp rõ nét 4 góc thẻ, đủ sáng, không lóa flash.": "Format: JPG, PNG, WEBP (Maximum 10MB). Encourage clear shots of all 4 corners of the card, bright enough, no flash glare.",
