  "Tự động gửi thông báo chi tiết (vi phạm cụ thể, cảnh báo, đề xuất cải thiện nội dung và lỗi chính tả phát hiện bởi AI) về email & tài khoản của Organizer.": "Automatically send detailed notifications (specific violations, warnings, content suggestions and AI-detected typos) to Organizer email & account.",
  "Hệ thống không lưu trữ tệp ảnh chụp thẻ CCCD. Danh tính công dân đã được xác thực sinh trắc học và đối soát trực tiếp với Cơ sở dữ liệu Quốc gia về Dân cư.": "The system does not store citizen ID card photos. Citizen identity is verified biometrically and cross-checked directly with the National Population Database.",
  "Khi bạn thêm mới, sửa đổi hoặc bật/tắt bất kỳ điều khoản nào, hệ thống AI sẽ đọc trực tiếp dữ liệu mới nhất vào prompt khi quét sự kiện, đảm bảo quyết định luôn chuẩn xác theo quy định hiện hành.": "Whenever you add, modify, or toggle any rule, the AI system immediately reads the latest data into the prompt during event review, ensuring decisions always align with current regulations.",
  "Tôi cam đoan toàn bộ thông tin sự kiện, giá vé, lịch trình, chính sách và các giấy phép tổ chức đính kèm là hoàn toàn chính xác, có hiệu lực pháp lý. Tôi chịu hoàn toàn trách nhiệm trước pháp luật và cam kết tuân thủ các quy định hoạt động của EventHub.": "I certify that all event information, ticket prices, schedules, policies, and attached permits are completely accurate and legally valid. I accept full legal responsibility and agree to comply with EventHub operating terms.",
  "Mỗi phiên cần ít nhất 1 loại vé hợp lệ (tên, giá >= 0, số lượng > 0)": "Each session requires at least 1 valid ticket tier (name, price >= 0, quantity > 0)",
  "mục": "items",
  "Đã import nội dung chính sách từ file .txt": "Imported policy content from .txt file",
  "Nhập hoặc import các điều khoản, quy định độ tuổi, trang phục, hoặc hướng dẫn bổ sung cho người giữ vé...": "Enter or import additional terms, age limits, dress code, or guidelines for ticket holders...",
  "loại vé": "ticket tier",
  "đã chọn": "selected",
  "Tôi cam kết sẽ thực hiện hoàn trả 100% tiền vé cho người mua trong vòng tối đa 7 ngày làm việc. Tôi hiểu rõ EventHub là nền tảng trung gian không giữ tiền vé, và toàn bộ nghĩa vụ tài chính hoàn tiền thuộc về Ban tổ chức.": "I commit to refunding 100% of ticket amounts to buyers within a maximum of 7 business days. I understand EventHub is an intermediary platform and does not hold ticket funds, and all refund obligations belong to the Organizer.",
  "Đăng nhập my.payos.vn bằng tài khoản của Ban tổ chức. Vào menu Thiết lập > chọn Hồ sơ, tìm mục Thay đổi dịch vụ, tick chọn Kênh chi (Payouts) và bấm Hoàn tất.": "Log in to my.payos.vn with the Organizer account. Go to Settings > Profile, find Change Services, check Payouts and click Complete.",
  "Kiểm tra kết nối Kênh chi": "Test Payouts Connection",
  "Tài khoản của bạn chưa được liên kết hoặc cấu hình kênh thanh toán PayOS (Client ID, API Key, Checksum Key). Để hệ thống có thể hoàn tiền tự động về tài khoản khách hàng, bạn cần thiết lập thông tin PayOS trong trang Cài đặt thanh toán.": "Your account is not yet linked or configured with PayOS payment channels (Client ID, API Key, Checksum Key). To allow automated refunds to customer accounts, configure your PayOS credentials in Payment Settings.",
  "Sự kiện này đã hết hiệu lực, đang ở bản nháp hoặc chưa được duyệt. Bạn chỉ có thể xem nhân sự, lời mời, thông số và báo cáo; không thể mời hoặc chỉnh sửa phân công.": "This event has expired, is a draft, or is unapproved. You can only view staff, invitations, metrics and reports; you cannot invite or edit assignments.",
